#include <stdio.h>
#include <string.h>

void longestPalindrome(char *s, char *result) {
    int n = strlen(s);
    int maxLen = 1, start = 0;
    for (int i = 0; i < n; i++) {
        // Odd length
        int l = i, r = i;
        while (l >= 0 && r < n && s[l] == s[r]) {
            if (r - l + 1 > maxLen) { maxLen = r - l + 1; start = l; }
            l--; r++;
        }
        // Even length
        l = i; r = i + 1;
        while (l >= 0 && r < n && s[l] == s[r]) {
            if (r - l + 1 > maxLen) { maxLen = r - l + 1; start = l; }
            l--; r++;
        }
    }
    strncpy(result, s + start, maxLen);
    result[maxLen] = '\0';
}

int main() {
    char s[1005], res[1005];
    if (scanf("%s", s) != 1) return 0;
    longestPalindrome(s, res);
    printf("%s\n", res);
    return 0;
}

