#include <stdio.h>
#include <string.h>

void multiplyStrings(char *s1, char *s2, char *result) {
    int n = strlen(s1), m = strlen(s2);
    int res[1000] = {0};
    for (int i = n - 1; i >= 0; i--) {
        for (int j = m - 1; j >= 0; j--) {
            int mul = (s1[i] - '0') * (s2[j] - '0');
            int sum = mul + res[i + j + 1];
            res[i + j + 1] = sum % 10;
            res[i + j] += sum / 10;
        }
    }
    int k = 0, i = 0;
    while (i < n + m - 1 && res[i] == 0) i++;
    for (; i < n + m; i++) result[k++] = res[i] + '0';
    result[k] = '\0';
}

int main() {
    char s1[500], s2[500], res[1005];
    if (scanf("%s %s", s1, s2) != 2) return 0;
    multiplyStrings(s1, s2, res);
    printf("%s\n", res);
    return 0;
}

