long long fact(int n) {
    long long f = 1;
    for (int i = 1; i <= n; i++) f *= i;
    return f;
}

long long findRank(char *s) {
    int n = strlen(s);
    long long rank = 1;
    for (int i = 0; i < n; i++) {
        int count = 0;
        for (int j = i + 1; j < n; j++) {
            if (s[j] < s[i]) count++;
        }
        rank += count * fact(n - i - 1);
    }
    return rank;
}

