#include <stdio.h>
#include <string.h>
#include <stdbool.h>

void alienOrder(char words[][50], int n, char *result) {
    int graph[26][26] = {0};
    int indegree[26] = {0};
    int used[26] = {0};
    for (int i = 0; i < n; i++) {
        for (int j = 0; words[i][j]; j++) used[words[i][j] - 'a'] = 1;
    }
    for (int i = 0; i < n - 1; i++) {
        int j = 0;
        while (words[i][j] && words[i+1][j] && words[i][j] == words[i+1][j]) j++;
        if (words[i][j] && words[i+1][j]) {
            int u = words[i][j] - 'a', v = words[i+1][j] - 'a';
            if (!graph[u][v]) {
                graph[u][v] = 1;
                indegree[v]++;
            }
        }
    }
    int k = 0;
    while (1) {
        int found = -1;
        for (int i = 0; i < 26; i++) {
            if (used[i] && indegree[i] == 0) { found = i; break; }
        }
        if (found == -1) break;
        result[k++] = found + 'a';
        used[found] = 0;
        for (int j = 0; j < 26; j++) {
            if (graph[found][j]) indegree[j]--;
        }
    }
    result[k] = '\0';
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    char words[500][50], result[30];
    for (int i = 0; i < n; i++) scanf("%s", words[i]);
    alienOrder(words, n, result);
    printf("%s\n", result);
    return 0;
}

