bool isPalindrome(char *s, int left, int right) {
    while (left < right) {
        if (s[left] != s[right]) return false;
        left++;
        right--;
    }
    return true;
}

int main() {
    char s[100005];
    int l, r;
    if (scanf("%s %d %d", s, &l, &r) != 3) return 0;
    printf(isPalindrome(s, l, r) ? "true\n" : "false\n");
    return 0;
}

