int rowDir[] = {-1, 1, 0, 0};
int colDir[] = {0, 0, -1, 1};

bool search(char grid[15][15], int r, int c, char *word, int idx, int R, int C, bool visited[15][15]) {
    if (word[idx] == '\0') return true;
    if (r < 0 || c < 0 || r >= R || c >= C || visited[r][c] || grid[r][c] != word[idx]) return false;
    visited[r][c] = true;
    for (int i = 0; i < 4; i++) {
        if (search(grid, r + rowDir[i], c + colDir[i], word, idx + 1, R, C, visited)) return true;
    }
    visited[r][c] = false;
    return false;
}

bool wordSearch(char grid[15][15], int R, int C, char *word) {
    bool visited[15][15] = {false};
    for (int i = 0; i < R; i++) {
        for (int j = 0; j < C; j++) {
            if (search(grid, i, j, word, 0, R, C, visited)) return true;
        }
    }
    return false;
}

int main() {
    int R, C;
    if (scanf("%d %d", &R, &C) != 2) return 0;
    char grid[15][15];
    for (int i = 0; i < R; i++) scanf("%s", grid[i]);
    char word[50];
    scanf("%s", word);
    printf(wordSearch(grid, R, C, word) ? "true\n" : "false\n");
    return 0;
}

