#include <iostream>
#include <string>
#include <stack>

using namespace std;

string decodeString(const string& s) {
    stack<string> strStack;
    stack<int> numStack;
    string curStr = "";
    int num = 0;
    for (char c : s) {
        if (isdigit(c)) {
            num = num * 10 + (c - '0');
        } else if (c == '[') {
            numStack.push(num);
            strStack.push(curStr);
            num = 0;
            curStr = "";
        } else if (c == ']') {
            int k = numStack.top(); numStack.pop();
            string prev = strStack.top(); strStack.pop();
            string repeated = "";
            while (k--) repeated += curStr;
            curStr = prev + repeated;
        } else {
            curStr += c;
        }
    }
    return curStr;
}

int main() {
    string s;
    if (cin >> s) {
        cout << decodeString(s) << endl;
    }
    return 0;
}

