#include <stdio.h>

void searchRange(int arr[], int n, int target, int *first, int *last) {
    *first = -1; *last = -1;
    int low = 0, high = n - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] >= target) high = mid - 1;
        else low = mid + 1;
    }
    if (low < n && arr[low] == target) *first = low;
    else return;

    low = 0; high = n - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] <= target) low = mid + 1;
        else high = mid - 1;
    }
    *last = high;
}

int main() {
    int n, target;
    if (scanf("%d", &n) != 1) return 0;
    int arr[n];
    for (int i = 0; i < n; i++) scanf("%d", &arr[i]);
    if (scanf("%d", &target) != 1) return 0;
    int f = -1, l = -1;
    searchRange(arr, n, target, &f, &l);
    printf("%d %d\n", f, l);
    return 0;
}

