#include <stdio.h>

int searchMatrix(int rows, int cols, int matrix[105][105], int target) {
    int low = 0, high = rows * cols - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        int r = mid / cols;
        int c = mid % cols;
        if (matrix[r][c] == target) return 1;
        else if (matrix[r][c] < target) low = mid + 1;
        else high = mid - 1;
    }
    return 0;
}

int main() {
    int r, c, target;
    if (scanf("%d %d", &r, &c) != 2) return 0;
    int mat[105][105];
    for (int i = 0; i < r; i++) {
        for (int j = 0; j < c; j++) scanf("%d", &mat[i][j]);
    }
    if (scanf("%d", &target) != 1) return 0;
    printf("%d\n", searchMatrix(r, c, mat, target));
    return 0;
}

