#include <stdio.h>

double findMedianSortedArrays(int a[], int m, int b[], int n) {
    if (m > n) return findMedianSortedArrays(b, n, a, m);
    int low = 0, high = m;
    while (low <= high) {
        int i = low + (high - low) / 2;
        int j = (m + n + 1) / 2 - i;
        int l1 = (i == 0) ? -2147483647 : a[i - 1];
        int r1 = (i == m) ? 2147483647 : a[i];
        int l2 = (j == 0) ? -2147483647 : b[j - 1];
        int r2 = (j == n) ? 2147483647 : b[j];

        if (l1 <= r2 && l2 <= r1) {
            if ((m + n) % 2 == 0) {
                int maxL = l1 > l2 ? l1 : l2;
                int minR = r1 < r2 ? r1 : r2;
                return (maxL + minR) / 2.0;
            } else {
                return (double)(l1 > l2 ? l1 : l2);
            }
        } else if (l1 > r2) {
            high = i - 1;
        } else {
            low = i + 1;
        }
    }
    return 0.0;
}

int main() {
    int m, n;
    if (scanf("%d", &m) != 1) return 0;
    int a[m > 0 ? m : 1];
    for (int i = 0; i < m; i++) scanf("%d", &a[i]);
    if (scanf("%d", &n) != 1) return 0;
    int b[n > 0 ? n : 1];
    for (int i = 0; i < n; i++) scanf("%d", &b[i]);
    printf("%.1f\n", findMedianSortedArrays(a, m, b, n));
    return 0;
}

