    if (a.size() > b.size()) return findMedianSortedArrays(b, a);
    int m = a.size(), n = b.size();
    int low = 0, high = m;
    while (low <= high) {
        int i = low + (high - low) / 2;
        int j = (m + n + 1) / 2 - i;
        int l1 = (i == 0) ? -1e9 : a[i - 1];
        int r1 = (i == m) ? 1e9 : a[i];
        int l2 = (j == 0) ? -1e9 : b[j - 1];
        int r2 = (j == n) ? 1e9 : b[j];

        if (l1 <= r2 && l2 <= r1) {
            if ((m + n) % 2 == 0) {
                return (max(l1, l2) + min(r1, r2)) / 2.0;
            } else {
                return max(l1, l2);
            }
        } else if (l1 > r2) {
            high = i - 1;
        } else {
            low = i + 1;
