#include <stdio.h>

int canAllocate(int arr[], int n, int students, long long limit) {
    int count = 1;
    long long pages = 0;
    for (int i = 0; i < n; i++) {
        if (arr[i] > limit) return 0;
        if (pages + arr[i] > limit) {
            count++;
            pages = arr[i];
        } else {
            pages += arr[i];
        }
    }
    return count <= students;
}

long long allocateBooks(int arr[], int n, int students) {
    if (students > n) return -1;
    long long low = 0, high = 0;
    for (int i = 0; i < n; i++) {
        if (arr[i] > low) low = arr[i];
        high += arr[i];
    }
    long long ans = high;
    while (low <= high) {
        long long mid = low + (high - low) / 2;
        if (canAllocate(arr, n, students, mid)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
}

int main() {
    int n, students;
    if (scanf("%d %d", &n, &students) != 2) return 0;
    int arr[n];
    for (int i = 0; i < n; i++) scanf("%d", &arr[i]);
    printf("%lld\n", allocateBooks(arr, n, students));
    return 0;
}

