bool canAllocate(const vector<int>& arr, int students, long long limit) {
    int count = 1;
    long long sum = 0;
    for (int p : arr) {
        if (p > limit) return false;
        if (sum + p > limit) {
            count++;
            sum = p;
        } else {
            sum += p;
        }
    }
    return count <= students;
}

long long allocateBooks(const vector<int>& arr, int students) {
    if (students > arr.size()) return -1;
    long long low = *max_element(arr.begin(), arr.end());
    long long high = accumulate(arr.begin(), arr.end(), 0LL);
    long long ans = high;
    while (low <= high) {
        long long mid = low + (high - low) / 2;
        if (canAllocate(arr, students, mid)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
}

int main() {
    int n, s;
    if (cin >> n >> s) {
        vector<int> arr(n);
        for (int i = 0; i < n; i++) cin >> arr[i];
        cout << allocateBooks(arr, s) << endl;
    }
    return 0;
}

