#include <stdio.h>

int countLessEqual(int matrix[][105], int n, int x) {
    int row = n - 1, col = 0, count = 0;
    while (row >= 0 && col < n) {
        if (matrix[row][col] <= x) {
            count += row + 1;
            col++;
        } else {
            row--;
        }
    }
    return count;
}

int kthSmallestMatrix(int matrix[][105], int n, int k) {
    int low = matrix[0][0], high = matrix[n - 1][n - 1];
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (countLessEqual(matrix, n, mid) < k) low = mid + 1;
        else high = mid;
    }
    return low;
}

int main() {
    int n, k;
    if (scanf("%d", &n) != 1) return 0;
    int mat[105][105];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) scanf("%d", &mat[i][j]);
    }
    if (scanf("%d", &k) != 1) return 0;
    printf("%d\n", kthSmallestMatrix(mat, n, k));
    return 0;
}

