#include <stdio.h>

int canSplit(int arr[], int n, int k, long long limit) {
    int count = 1;
    long long sum = 0;
    for (int i = 0; i < n; i++) {
        if (arr[i] > limit) return 0;
        if (sum + arr[i] > limit) {
            count++;
            sum = arr[i];
        } else {
            sum += arr[i];
        }
    }
    return count <= k;
}

long long splitArray(int arr[], int n, int k) {
    if (k < 1 || k > n) return -1;
    long long low = 0, high = 0;
    for (int i = 0; i < n; i++) {
        if (arr[i] > low) low = arr[i];
        high += arr[i];
    }
    while (low < high) {
        long long mid = low + (high - low) / 2;
        if (canSplit(arr, n, k, mid)) high = mid;
        else low = mid + 1;
    }
    return low;
}

int main() {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;
    int arr[n];
    for (int i = 0; i < n; i++) scanf("%d", &arr[i]);
    printf("%lld\n", splitArray(arr, n, k));
    return 0;
}

