{"c": "#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX 10000

typedef struct {
    int arr[MAX];
    int top;
} Stack;

void init(Stack *s) {
    s->top = -1;
}

void push(Stack *s, int x) {
    s->arr[++(s->top)] = x;
}

int pop(Stack *s) {
    if (s->top == -1) return -1;
    return s->arr[(s->top)--];
}

int peek(Stack *s) {
    if (s->top == -1) return -1;
    return s->arr[s->top];
}

bool isEmpty(Stack *s) {
    return s->top == -1;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    Stack s;
    init(&s);
    for (int i = 0; i < n; i++) {
        char op[20];
        scanf("%s", op);
        if (strcmp(op, "push") == 0) {
            int x; scanf("%d", &x);
            push(&s, x);
        } else if (strcmp(op, "pop") == 0) {
            printf("%d\n", pop(&s));
        } else if (strcmp(op, "peek") == 0) {
            printf("%d\n", peek(&s));
        } else if (strcmp(op, "isEmpty") == 0) {
            printf("%s\n", isEmpty(&s) ? "True" : "False");
        }
    }
    return 0;
