    s->top = -1;
    s->min_top = -1;
}

void push(MinStack *s, int val) {
    s->stack[++(s->top)] = val;
    if (s->min_top == -1 || val <= s->min_stack[s->min_top]) {
        s->min_stack[++(s->min_top)] = val;
    }
