        } else if (ch == ']') {
            int repeat = count_stack[top];
            char prev[10005];
            strcpy(prev, str_stack[top]);
            top--;

            char temp[10005] = "";
            for (int r = 0; r < repeat; r++) {
                strcat(temp, curr_str);
            }
            strcpy(curr_str, prev);
            strcat(curr_str, temp);
        } else {
            int len = strlen(curr_str);
