def totalNQueens(n):
    count = 0
    cols = set()
    diagonals1 = set()
    diagonals2 = set()

    def backtrack(row):
        nonlocal count
        if row == n:
            count += 1
            return

        for col in range(n):
            d1 = row - col
            d2 = row + col
            if col in cols or d1 in diagonals1 or d2 in diagonals2:
                continue

            cols.add(col)
            diagonals1.add(d1)
            diagonals2.add(d2)

            backtrack(row + 1)

            cols.remove(col)
            diagonals1.remove(d1)
            diagonals2.remove(d2)

    backtrack(0)
    return count

