        while (!q.isEmpty()) {
            Node curr = q.poll();
            if (!first) sb.append(" ");
            first = false;
            if (curr == null) {
                sb.append("N");
            } else {
                sb.append(curr.val);
                q.add(curr.left);
                q.add(curr.right);
            }
        }
        return sb.toString();
    }

