from collections import deque

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def build_tree(values):
    if not values or values[0] == 'N':
        return None
    root = Node(int(values[0]))
    q = deque([root])
    i = 1
    while q and i < len(values):
        node = q.popleft()
        if values[i] != 'N':
            node.left = Node(int(values[i]))
            q.append(node.left)
        i += 1
        if i < len(values) and values[i] != 'N':
            node.right = Node(int(values[i]))
            q.append(node.right)
        i += 1
    return root

def recover_tree(root):
    first = second = prev = None
    def inorder_check(node):
        nonlocal first, second, prev
        if not node:
            return
        inorder_check(node.left)
        if prev and prev.val > node.val:
            if first is None:
                first = prev
            second = node
        prev = node
        inorder_check(node.right)
    inorder_check(root)
    if first and second:
        first.val, second.val = second.val, first.val
    return root

def inorder(root):
    if not root:
        return []
    return inorder(root.left) + [root.val] + inorder(root.right)

if __name__ == '__main__':
    raw = sys.stdin.read().replace('/', ' ').split()
    if raw:
        n = int(raw[0])
        values = raw[1:]
        root = build_tree(values)
        root = recover_tree(root)
        print(inorder(root))"}

