from collections import deque

def topological_sort(n, graph):
    indegree = [0] * n

    for u in range(n):
        for v in graph[u]:
            indegree[v] += 1

    q = deque(i for i in range(n) if indegree[i] == 0)
    result = []

    while q:
        node = q.popleft()
        result.append(node)

        for neighbor in sorted(graph[node]):
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                q.append(neighbor)

